html.head:
        COMPONENT










































///////// 1. 변수 및 선언 영역 /////////
scwin.selIndex = ""; // 선택된 Element 실제 행 인덱스
scwin.rlstJson = ""; // 그리드 drillDown 특성에 따라 복원하는 변수
scwin.heightOpt = {maxHeight:"405px", minHeight:"191px"}; // 가변형 그리드 크기

///////// 2. 초기화 영역 /////////
            /**
             * @method
             * @name onpageload
             * @description 화면 진입점 — 파라미터(txnId)를 수신해 엘리먼트 트리를 조회(fnSearch)하고 Enum 목록·그리드 표시 상태를 초기화한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example (body ev:onpageload 바인딩으로 자동 호출)
             */
            scwin.onpageload = function (e) {

                dma_search.set("txnId", $c.data.getParameter("txnId"));
                // 조회
                scwin.fnSearch();
                // 초기화
                dlt_list2.removeAll();

                grd_list1.setGridHeight(scwin.heightOpt.maxHeight);
                grp_enum1.setStyle("display", "none");
                grp_enum2.setStyle("display", "none");
            };

///////// 3. 컴포넌트 이벤트 영역 /////////
            /**
             * @method
             * @name btn_search_onclick
             * @description [조회] 버튼 클릭 — 엘리먼트 트리를 재조회한다(fnSearch).
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.btn_search_onclick(e);
             */
            scwin.btn_search_onclick = function (e) {

                scwin.fnSearch();
            };

            /**
             * @method
             * @name chk_abstract_onviewchange
             * @description Abstract 항목 표시 체크 변경 — 해제 시 Abstract 행을 제외하고 레벨(elmtLvl)을 재조정해 목록을 재구성한다.
             * @param {Object} info 선택/값 변경 정보
             * @returns {void}
             * @hidden N
             * @example scwin.chk_abstract_onviewchange(info);
             */
            scwin.chk_abstract_onviewchange = function (info) {

                const val = info.newValue === "Y"?"Y":"N";                              
                if (val === "N") {         
                    // WebSquare Deep Copy(원본 손상없이 처리)
                    const data = JSON.parse(JSON.stringify(scwin.rlstJson));
                    // 위치 재조정
                    const result = [];
                    let offset = 0;
                    for (let i=0; i < data.length; i++) {
                        const row = data[i];

                        if (row.abstractYn === "Y") {
                            // 기준 갱신
                            offset = row.elmtLvl;
                            continue;
                        }                        
                        row.elmtLvl = row.elmtLvl - offset;
                        // 계산 후  elmtLvl 0보다 작거나 같은 경우가 발생하면 강제적으로 "1" Level 조정
                        if (row.elmtLvl < 1) {
                            row.elmtLvl = 1;
                        }
                        result.push(row);
                    }
                    dlt_list1.setJSON(result);
                } else {
                    dlt_list1.setJSON(scwin.rlstJson);
                }

                if (chk_spanAll.getValue() === "Y") {
                    // 전체 펼치기
                    grd_list1.spanAll(true);
                } else {
                    grd_list1.spanAll(2);
                }                   
                scwin.fnButtonVisible();
                // 초기화
                dlt_list2.removeAll();
                tbx_element.setValue("");                
                scwin.selIndex = "";
            };

            /**
             * @method
             * @name chk_spanAll_onviewchange
             * @description 전체 펼치기 체크 변경 — 트리를 전체 펼치거나 2레벨까지만 펼친다.
             * @param {Object} info 선택/값 변경 정보
             * @returns {void}
             * @hidden N
             * @example scwin.chk_spanAll_onviewchange(info);
             */
            scwin.chk_spanAll_onviewchange = function (info) {

                const val = info.newValue === "Y"?"Y":"N";
                if (val === "Y") {         
                    grd_list1.spanAll(true);
                } else {
                    grd_list1.spanAll(2);
                }
            };

            /**
             * @method
             * @name ibx_searchKeyword_onkeyup
             * @description 검색 키워드 입력란 키 입력 — Enter 시 재조회한다(fnSearch).
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.ibx_searchKeyword_onkeyup(e);
             */
            scwin.ibx_searchKeyword_onkeyup = function (e) {

                if (e.key === "Enter") {                    
                    scwin.fnSearch();
                }
            };

            /**
             * @method
             * @name grd_list1_oncellclick
             * @description 목록 셀 클릭 — 선택 버튼 컬럼 클릭 시 실제 행 인덱스(getRealRowIndex) 기준으로 선택 상태를 갱신하고 Enum 타입이면 참조값 목록(dlt_list2)을 구성한다.
             * @param {Number} rowIndex 행 인덱스
             * @param {Number} columnIndex 열 인덱스
             * @param {String} columnId 컬럼 ID
             * @returns {void}
             * @hidden N
             * @example scwin.grd_list1_oncellclick(0, 1, "isButton");
             */
            scwin.grd_list1_oncellclick = function (rowIndex, columnIndex, columnId) {

                // 보이는 건수  
                tbx_mark.setValue(dlt_list1.getRowCount());                                      
                if (columnId === "isButton") {
                    // 웹스퀘어는 트리형태로 사용 할 경우 보이는 rowIndex 기준으로 하기 때문에 close된 항목이
                    // 있을 경우 rowIndex가 틀어져 버리는 문제가 있어 getRealRowIndex를 필수로 사용
                    const realIndex = grd_list1.getRealRowIndex(rowIndex);
                    // 그리드 값 변경                    
                    dlt_list1.setCellData(realIndex, "isButton", "선택됨");
                    if (!$c.util.isEmpty(scwin.selIndex) && realIndex !== scwin.selIndex) {
                        dlt_list1.setCellData(scwin.selIndex, "isButton", "선택");
                    }
                    scwin.selIndex = realIndex;
                    tbx_element.setValue(dlt_list1.getCellData(realIndex, "elmtKorLabl") + "(" + dlt_list1.getCellData(realIndex, "elmtId") + ")");

                    // 초기화
                    dlt_list2.removeAll();
                    // Enumeration으로 선택지가 있는지 체크
                    if (dlt_list1.getCellData(realIndex, "enumYn") === "Y") {
                        const items = (dlt_list1.getCellData(realIndex, "enumList")).split("|");

                        const result = [];                        
                        items.forEach(item => {
                            const data_ = {};
                            const parts = item.split(":");
                            if (parts.length === 3) {
                                const [value, korLabel, engLabel] = parts;
                                data_.setValue(value);
                                data_.korLabel = korLabel;
                                data_.engLabel = engLabel;
                            } else if (parts.length === 2) {
                                const [value, korLabel] = parts;
                                data_.setValue(value);
                                data_.korLabel = korLabel;
                            } else {
                                const [value] = parts;
                                data_.setValue(value);    
                            }
                            data_.enumInfo = item;

                            result.push(data_);
                        });
                        dlt_list2.setJSON(result);

                        grd_list1.setGridHeight(scwin.heightOpt.minHeight);
                        grp_enum1.setStyle("display", "");
                        grp_enum2.setStyle("display", "");

                        let height = 0;
                        if (chk_abstract.getValue() === "Y") {
                            height = (rowIndex * 25) - 216;
                            console.log(height);
                            if (height > 1000) {                         
                                height = height - (216 * (Math.floor(height / 1000)));
                            }
                            grd_list1.setScrollTop(height);  
                        }                         
                    } else {
                        grd_list1.setGridHeight(scwin.heightOpt.maxHeight);
                        grp_enum1.setStyle("display", "none");
                        grp_enum2.setStyle("display", "none");
                    }                    
                    // 웹스퀘어가 그리드에 변경이 있을 경우 내부적으로 redraw처리해서 DOM을 이용해 구현된 로직은
                    // 초기화 하는 문제가 발생하므로 DOM을 이용한 로직은 마지막에 처리하게 수정 
                    scwin.fnButtonProc();
                }
            };

            /**
             * @method
             * @name grd_list1_onscrolly
             * @description 목록 세로 스크롤 — 선택 행이 있으면 버튼 스타일을 재적용한다(fnButtonProc).
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.grd_list1_onscrolly(e);
             */
            scwin.grd_list1_onscrolly = function (e) {

                // 기존에 체크되서 변경되어 정보 있는지 체크
                if (!$c.util.isEmpty(scwin.selIndex)) {
                    scwin.fnButtonProc();
                }                
            };

            /**
             * @method
             * @name grd_list1_ontoggleclick
             * @description 트리 토글 클릭 — 펼침 시 선택 버튼 스타일을 재적용한다(fnButtonProc).
             * @param {Boolean} collapsed 접힘 여부
             * @param {Number} rowIndex 행 인덱스
             * @returns {void}
             * @hidden N
             * @example scwin.grd_list1_ontoggleclick(false, 0);
             */
            scwin.grd_list1_ontoggleclick = function (collapsed, rowIndex) {

                // 기존에 체크되서 변경되어 정보 있는지 체크
                if (!$c.util.isEmpty(scwin.selIndex) && !collapsed) {
                    scwin.fnButtonProc();
                }
            };

            /**
             * @method
             * @name btn_select_onclick
             * @description [확인] 버튼 클릭 — 선택된 Element 정보(ID·라벨·선택 참조값)를 수집해 부모창으로 반환하고 팝업을 닫는다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.btn_select_onclick(e);
             */
            scwin.btn_select_onclick = function (e) {

                if (!$c.util.isEmpty(scwin.selIndex)) {
                    const params = {};
                    params.elmtId = dlt_list1.getCellData(scwin.selIndex, "elmtId");
                    params.elmtKorLabl = dlt_list1.getCellData(scwin.selIndex, "elmtKorLabl");
                    params.elmtEngLabl = dlt_list1.getCellData(scwin.selIndex, "elmtEngLabl");

                    const result = [];
                    if (dlt_list2.getRowCount() > 0) {
                        // 참조값 체크
                        for (let i=0; i < dlt_list2.getRowCount(); i++) {
                            if (dlt_list2.getCellData(i, "CHK")) {                                
                                result.push(dlt_list2.getCellData(i, "enumInfo"));
                            }                         
                        }
                        // 1개이상 선택이 필요
                        if (result.length < 1) {
                            $c.win.alert("1개이상 참조값을 선택 해주세요.");
                            return;
                        }                        
                    }
                    params.enumList = result;                    
                    $c.win.closePopup(params);
                } else {
                    $c.win.alert("Element를 선택 해주세요.");
                }
            };

            /**
             * @method
             * @name btn_close_onclick
             * @description [취소] 버튼 클릭 — 팝업을 닫는다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.btn_close_onclick(e);
             */
            scwin.btn_close_onclick = function (e) {

                $c.win.closePopup();
            };

///////// 4. 서브미션 콜백 영역 /////////
            /**
             * @method
             * @name sbm_list_submitdone
             * @description sbm_list(엘리먼트 트리 조회) 완료 콜백 — 성공 시 전체 결과를 보관(rlstJson)하고 펼침·버튼 표시 상태를 갱신하며 실패 시 오류 메시지를 표시한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example (xf:submission sbm_list ev:submitdone 바인딩으로 자동 호출)
             */
            scwin.sbm_list_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    // Filter적용을 위해 전체 결과를 임시 저장
                    scwin.rlstJson = result.body;

                    if (chk_spanAll.getValue() === "Y") {
                        // 전체 펼치기
                        grd_list1.spanAll(true);
                    }                    

                    // 버튼 숨김 처리
                    scwin.fnButtonVisible();                    
                } else {
                    $c.win.alert(result.message);
                }
            };

///////// 5. 일반/업무 함수 영역 /////////
            /**
             * @method
             * @name fnSearch
             * @description 엘리먼트 트리 조회 — dma_search 조건으로 sbm_list 를 실행한다.
             * @returns {void}
             * @hidden N
             * @example scwin.fnSearch();
             */
            scwin.fnSearch = function () {

                // 조회 
                $c.sbm.execute(sbm_list, dma_search.getJSON());
            };

            /**
             * @method
             * @name fnButtonVisible
             * @description LineItem 이 아닌 행의 선택 버튼을 숨기고 총건수·표시건수를 갱신한다.
             * @returns {void}
             * @hidden N
             * @example scwin.fnButtonVisible();
             */
            scwin.fnButtonVisible = function () {

                for (let i=0; i < dlt_list1.getRowCount(); i++) {                    
                    if (dlt_list1.getCellData(i, "lineItemYn") !== "Y") {
                        grd_list1.setCellStyle(i, "isButton", "visibility", "hidden");
                    }                           
                }
                // 총건수 
                tbx_total.setValue(dlt_list1.getRowCount());
                // 보이는 건수  
                tbx_mark.setValue(dlt_list1.getRowCount());
            };

            /**
             * @method
             * @name fnButtonProc
             * @description 선택됨 상태의 그리드 버튼 스타일을 일괄 적용한다($c.tms.setGridButton).
             * @returns {void}
             * @hidden N
             * @example scwin.fnButtonProc();
             */
            scwin.fnButtonProc = function () {

                // 그리드 button 스타일 변경
                const options = {
                    target: "선택됨",
                    backColor: "blue",
                    color: "white",
                    resBackColor: "white",
                    resColor: "black"
                };                    
                $c.tms.setGridButton(grd_list1, options);
            };



        .myBtn {
            background-color: #4CAF50;
            color: blue;
        }
